CREATE TABLE customers(id INTEGER PRIMARY KEY, name TEXT, city TEXT, grade TEXT, joined TEXT, referrer_id INTEGER);
CREATE TABLE products(id INTEGER PRIMARY KEY, name TEXT, category TEXT, price INTEGER, stock INTEGER);
CREATE TABLE orders(id INTEGER PRIMARY KEY, customer_id INTEGER, order_date TEXT, status TEXT);
CREATE TABLE order_items(order_id INTEGER, product_id INTEGER, qty INTEGER);
